SELECT order_id, STDDEV_SAMP(unit_price) AS unit_price_stddev, BIT_OR(quantity) AS quantity_bit_or, APPROX_PERCENTILE(unit_price, ARRAY(0.25, 0.5, 0.75)) AS unit_price_quartiles, PERCENTILE_APPROX(unit_price, 0.95) AS unit_price_p95, CORR(quantity, unit_price) AS corr_quantity_unit_price, STDDEV_SAMP(unit_price) AS unit_price_stddev_2 FROM order_items GROUP BY order_id ORDER BY unit_price_stddev;
